'use strict';
let robustFamily='All checks',robustPicked='base_ridge';
const ROBUST_LABELS={base_ar:['Original models','Use recent price changes','A simple model learns from earlier price movements.'],base_ridge:['Original models','Use market inputs','A regression adds inventory, production, demand and volatility inputs.'],base_boost:['Original models','Use a tree-based model','A more flexible model looks for nonlinear patterns.'],window_252:['History length','Learn from the most recent year','Cap the training history at 252 completed examples.'],window_504:['History length','Learn from about two years','Cap the training history at 504 completed examples.'],window_756:['History length','Learn from about three years','Cap the training history at 756 completed examples.'],weekly_lag_7:['Data timing','Use weekly data after seven days','Change when weekly information becomes available to the model.'],weekly_lag_14:['Data timing','Wait fourteen days for weekly data','Test a more conservative delay before using weekly information.'],daily_lag_2:['Data timing','Wait two days for daily inputs','Delay other daily market indicators by an extra day.'],ridge_alpha_10:['Model settings','Allow a more flexible regression','Reduce the penalty on large regression coefficients.'],ridge_alpha_1000:['Model settings','Use a more restrained regression','Increase the penalty on large regression coefficients.'],boost_leaves_3:['Model settings','Use smaller decision trees','Allow fewer branches in the tree-based model.'],boost_leaves_15:['Model settings','Use larger decision trees','Allow more branches in the tree-based model.'],omit_risk:['Market inputs','Remove volatility inputs','Leave out VIX and OVX and test again.'],omit_inventory:['Market inputs','Remove inventory information','Leave out inventory levels and changes.'],omit_production:['Market inputs','Remove production information','Leave out production levels and changes.'],omit_demand:['Market inputs','Remove the demand proxy','Leave out US product supplied and its changes.'],omit_brent:['Market inputs','Remove Brent prices','Leave out the delayed Brent price input.'],exclude_2020_training:['Extreme episode','Learn without the 2020 shock','Remove training examples touching the 2020 shock period.']};
function robustVisual(){
 const B=window.ROBUSTNESS,h=+$('robustHorizon').value,all=B.metrics.filter(z=>z.group==='daily'&&z.period==='All'&&z.horizon===h),wins=all.filter(z=>z.relative_mae<1).length;
 $('robustCount').innerHTML=`<strong>${wins}</strong><span>of ${all.length} setups</span>`;
 $('robustHeadline').textContent=wins===0?'None improved on the no-change forecast.':`Only ${wins} setups had a smaller prediction error.`;
 $('robustPlain').textContent=wins===0?'The main finding holds at this horizon: extra complexity did not bring a consistent advantage.':'A few settings helped slightly here. They did not keep that advantage across the longer horizons.';
 const families=['All checks','Original models','History length','Data timing','Model settings','Market inputs','Extreme episode'];
 $('robustFamilies').innerHTML=families.map(f=>`<button type="button" data-family="${f}" aria-pressed="${f===robustFamily}">${f}</button>`).join('');
 document.querySelectorAll('[data-family]').forEach(b=>b.onclick=()=>{robustFamily=b.dataset.family;robustVisual();});
 const rows=all.filter(z=>robustFamily==='All checks'||ROBUST_LABELS[z.spec][0]===robustFamily);
 if(!rows.some(z=>z.spec===robustPicked))robustPicked=rows[0].spec;
 $('robustDots').innerHTML=rows.map(z=>{let n=all.findIndex(q=>q.spec===z.spec)+1,label=ROBUST_LABELS[z.spec][1],delta=(z.relative_mae-1)*100;return `<button type="button" class="test-dot ${delta<0?'better':'worse'}" data-spec="${z.spec}" aria-pressed="${z.spec===robustPicked}" aria-label="${label}: ${fmt(Math.abs(delta),1)} percent ${delta<0?'lower':'higher'} error"><span>${n}</span><span class="dot-tooltip">${label}</span></button>`;}).join('');
 document.querySelectorAll('[data-spec]').forEach(b=>b.onclick=()=>{robustPicked=b.dataset.spec;robustVisual();});
 const z=rows.find(z=>z.spec===robustPicked),labels=ROBUST_LABELS[z.spec],delta=(z.relative_mae-1)*100,max=Math.max(z.mae,z.rw_mae)*1.15;
 $('robustFactor').textContent=labels[0];$('robustSelectedTitle').textContent=labels[1];$('robustSelectedText').textContent=labels[2];
 $('robustComparison').innerHTML=`<div class="error-bar-row"><span>No-change forecast</span><div><i style="width:${z.rw_mae/max*100}%" class="reference-error"></i></div><b>${money(z.rw_mae)}</b></div><div class="error-bar-row"><span>This setup</span><div><i style="width:${z.mae/max*100}%" class="${delta<0?'better-error':'worse-error'}"></i></div><b>${money(z.mae)}</b></div><p class="comparison-verdict ${delta<0?'better-text':''}">${fmt(Math.abs(delta),1)}% ${delta<0?'lower':'higher'} average error</p>`;
 $('robustSelectedNote').textContent=`Average absolute error in dollars per barrel. Lower is better. Both forecasts use the same ${z.n} dates. One step is one observed WTI price, rather than a calendar day. Results describe this tested sample, not a reliability percentage.`;
 robustYearVisual();
}
function robustYearVisual(){
 const h=+$('robustHorizon').value,model=$('robustYearModel').value,rows=window.ROBUSTNESS.slices.filter(z=>z.horizon===h&&z.model===model&&/^202[1-6]$/.test(z.period));
 const extent=Math.max(10,...rows.map(z=>Math.abs(z.difference/z.rw_mae*100)))*1.18,zero=430,scale=240/extent;
 let svg='<svg viewBox="0 0 850 300" xmlns="http://www.w3.org/2000/svg"><text x="65" y="22" font-size="12" fill="#087e83">← Lower error</text><text x="575" y="22" font-size="12" fill="#a85f37">Higher error →</text><line x1="430" x2="430" y1="35" y2="266" stroke="#84948c" stroke-dasharray="4 4"/>';
 rows.forEach((z,i)=>{let d=z.difference/z.rw_mae*100,y=48+i*35,w=Math.abs(d)*scale;svg+=`<text x="65" y="${y+16}" font-size="13" fill="#183737">${z.period}</text><rect x="${d<0?zero-w:zero}" y="${y}" width="${Math.max(1,w)}" height="21" rx="2" fill="${d<0?'#087e83':'#c99576'}"><title>${z.period}: ${fmt(d,1)}% error difference; ${z.n} forecasts</title></rect><text x="${d<0?zero-w-9:zero+w+9}" y="${y+16}" text-anchor="${d<0?'end':'start'}" font-size="12" fill="#183737">${d>0?'+':''}${fmt(d,1)}%</text>`;});
 svg+='<text x="430" y="290" text-anchor="middle" font-size="11" fill="#566d69">0 = the same average error as the no-change forecast</text></svg>';$('robustYearChart').innerHTML=svg;
}
$('robustYearModel').onchange=robustYearVisual;
robustVisual();
